INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (31, 'Page d\'accueil', 'page-daccueil-mon-projet-agricole', 'Mon projet agricole', '<h2>Titre Section</h2><p>Provident deserunt nostrum omnis dolores impedit voluptates iure. Ut nobis neque quisquam excepturi voluptatem perspiciatis neque. Velit magnam autem minus saepe dolorum. Quo esse modi eligendi.\n\nFacere eos ut perspiciatis quis sint commodi qui. Quia et molestiae expedita sint laboriosam. Dolores consequatur qui dignissimos qui ut at ipsam. Ab quia magnam soluta sit.</p>', '2020-08-28 16:47:20', '2020-08-28 16:47:20', 0);
