INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (32, 'Qui sommes-nous?', 'qui-sommes-nous-texte-dintroduction-sous-le-titre-principal', 'Texte d’introduction sous le titre principal', '<h1>A propos d\'Objectif Terres</h1><h2>Une plateforme, deux services en faveur de l\'installation et de la transmission agricole&nbsp;</h2><blockquote><p>Objectif Terres est une plateforme de mise en liens autour des terres agricoles, pour faciliter l’accès au foncier et la reprise des fermes. Ce service, proposé par Terre de Liens, s’inscrit donc dans une démarche de préservation des terres agricoles et dans le développement d’une agriculture biologique et paysanne nourricière. Pour cela, Terre de Liens s’inscrit et travaille en coopération avec un réseau d’acteurs de l’accompagnement du développement agricole et rural, notamment membres du réseau <a href="http://agricultures-alternatives.org/rubrique12.html">InPACT</a>.</p></blockquote><p>Objectif Terres, c’est à la fois :</p><ul><li><strong>un site de petites annonces</strong> à destination des particuliers et des professionnels de l’accompagnement, pour <strong>faciliter la rencontre entre les offres et les recherches de foncier agricole</strong>, pour faciliter la reprise des fermes et permettre l’installation de nouveaux paysan-ne-s en bio. Ces annonces s’adressent tout particulièrement : <strong>aux personnes qui sont en recherches de terres</strong>, <strong>à celles et ceux qui ont un bien agricole</strong> (ou avec un potentiel agricole) à transmettre mais aussi à toutes les <strong>personnes qui souhaitent se former, intégrer un projet agricole existant ou encore mobiliser de nouvelles personnes pour en initier un</strong>. Vous pouvez consulter <strong>gratuitement</strong> l’ensemble des annonces publiées, mais aussi contacter et interagir directement avec les annonceurs de votre choix.</li><li><strong>une porte d’entrée pour se faire accueillir, orienter et accompagner sur le volet foncier de votre projet par l’une des 19 associations régionales de Terre de Liens ; </strong>après nous avoir livré quelques informations sur votre projet, vous serez recontactés par des bénévoles et salariés de Terre de Liens en charge de l’accompagnement des projets. Le délai de réponse ainsi que les modalités d’accompagnement pourront différer en fonction de votre projet et de votre territoire, selon les disponibilités et compétences présentes sur le territoire.</li></ul><p>&nbsp;</p><p><strong>Consulter la charte d’utilisation d’Objectif Terres : <a target="_blank" href="https://www.objectif-terres.org/docs/OT_charte_oct2020.pdf">consulter la charte</a></strong></p><p>&nbsp;</p><h2>Ils et elles font vivre Objectif Terres</h2><p>Derrière ce service numérique, il y a des hommes et des femmes de toute la France qui se mobilisent au quotidien pour modérer votre annonce, répondre à une question technique, vous orienter vers le bon contact, vous guider dans votre stratégie de recherche de foncier…</p><p><strong>Il s’agit autant de bénévoles engagé-es que de salarié-es du réseau associatif Terre de Liens</strong> : il faut compter une équipe d’une trentaine de modérateurs et modératrices pour les annonces foncières et compter plus d’une quarantaine de personnes en charge de vous accompagner quotidiennement !</p><p>&nbsp;</p><p>&nbsp;</p>', '2020-08-28 16:47:20', '2020-09-16 15:19:19', 0);


DELETE FROM `cms_pages` WHERE `id`=33;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (33, 'Qui sommes-nous?', 'qui-sommes-nous-les-deux-textes-situes-sous-la-banniere', 'Les deux textes situés sous la bannière', '<h2>Ils nous soutiennent</h2><p>&nbsp;</p><p>Avec la contribution de :&nbsp;</p><figure class="image"><img src="https://objectif-terres.kaffein.agency/storage/attachments/la-responsabilite-du-ministere-ne-saurait-etre-engagee-5f6b4060e1808.jpeg"></figure><p>&nbsp;</p><h2><strong>La démarche numérique derrière Objectif Terres</strong></h2><p>&nbsp;</p><p>Pour développer un service numérique en cohérence avec ses valeurs, Terre de Liens s’est tourné vers des prestataires engagés dans l’utilisation de logiciels libres de droit, open-source et engagés dans la réduction de la consommation énergétique liée nos pratiques numériques. Le site est hébergé au cœur de l’Auvergne, sur les serveurs O2Switch.</p><p>&nbsp;</p><p><strong>Les développeurs</strong></p> <p><br>Kaffein Agency s\'inscrit dans une logique open-source, green-code, et favorise les logiciels libres. C\'est une <a href="https://www.kaffein.agency/" target="_blank">agence web Lyonnaise</a> de communication, développement web et application mobile, qui place l\'humain au centre de ses projets. Notre point commun avec Objectif Terres est l''entraide dans nos différentes communautés, savoir mettre de côté le profit pour redonner un sens à nos échanges économiques.</p><br><br>', '2020-08-28 16:47:20', '2020-09-24 12:15:42', 0);


DELETE FROM `cms_pages` WHERE `id`=34;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (34, 'Qui sommes-nous?', 'hyvMKcK55N2eY5bDQX1kkr6xJxx6lhaG', 'En savoir plus sur l’association  Terre de Liens', '<h2>Terre de Liens en bref</h2><p>Terre de Liens est né en 2003 de la convergence de plusieurs mouvements liant l’éducation populaire, l’agriculture biologique et biodynamique, la finance éthique, l’économie solidaire et le développement rural.</p><p>Pour permettre à des citoyens et des paysans de se mobiliser et d’agir sur le terrain, le mouvement a inventé de nouveaux outils de travail capables d’enrayer la disparition des terres et de faciliter l’accès au foncier agricole pour de nouvelles installations paysannes. Ces outils sont à la portée de tous, de sorte que chacun puisse s’impliquer de façon effective dans l’avenir de nos fermes et de notre agriculture.</p><p>&nbsp;</p><p>&lt;iframe width="424" height="238" src="https://www.youtube.com/embed/ZS8mbB4kl1Q" frameborder="0" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen&gt;&lt;/iframe&gt;</p><p>&nbsp;</p><p><strong>L’originalité de Terre de Liens vient d’une triple articulation&nbsp;</strong></p><ul><li>Un réseau associatif mobilisé partout en France : il accueille et accompagne les paysans pour leur accès à la terre ou leur transmission, informe et rassemble le public autour des enjeux fonciers et agricoles, et ancre le projet Terre de Liens dans une dynamique citoyenne et locale.</li><li>La Foncière, entreprise d’investissement solidaire ouverte aux citoyens, permet à chacun de placer son épargne dans un projet à haute valeur sociale et écologique. Le capital accumulé sert à acheter des fermes pour y implanter des activités agri-rurales diversifiées. La Foncière loue ces fermes à des paysans engagés dans une agriculture de proximité, biologique et à taille humaine.</li><li>La Fondation, reconnue d’utilité publique, est habilitée à recevoir des legs et donations de fermes. Elle achète aussi des terres qui risquent de perdre leur usage agricole. Dans tous les cas, la Fondation garantit sur ces terres des pratiques agricoles respectueuses de l’environnement à très long terme. Terre de Liens participe ainsi à la relève agricole et facilite la transmission intergénérationnelle en installant de nouveaux paysans.</li></ul><p>&nbsp;</p><p><strong>C’est cette action combinée qui permet :</strong></p><ul><li>d’acquérir des terres agricoles et éviter ainsi leur disparition</li><li>d’en assurer la préservation à long terme par un usage écologique et responsable</li><li>de mettre ces terres en location à des agriculteurs, pour une production biologique ou paysanne</li><li>de partager le fruit de ces expériences avec tous les acteurs intéressés</li><li>d’inventer de nouvelles réponses à la crise du foncier agricole et de réunir citoyens, décideurs et acteurs agricoles autour de ces perspectives</li></ul><p>&nbsp;</p><p>Consulter la charte et les valeurs de Terre de Liens : <a href="https://ressources.terredeliens.org/les-ressources/charte-de-terre-de-liens">https://ressources.terredeliens.org/les-ressources/charte-de-terre-de-liens</a></p><p>Pour en savoir plus sur notre mouvement :&nbsp;</p><p><a href="https://terredeliens.org/">https://terredeliens.org/</a></p>', '2020-08-28 16:47:20', '2020-09-23 09:50:36', 0);
DELETE FROM `cms_pages` WHERE `id`=35;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (35, 'Transmettre ma ferme', 'transmettre-ma-ferme', 'Contenu de la page "Transmettre ma ferme"', '<p>Pour vous aider, vous inspirer et vous outiller dans votre projet d’installation ou de transmission agricole, Terre de Liens et ses partenaires du réseau InPACT (Initiatives pour une Agriculture citoyenne et territoriale) ont édité un ensemble de guides méthodologiques et recueilli une diversité de projets réussis et inspirants d’installations et de transmissions.</p><p>L’ensemble de ces ressources vous sont mises à disposition gratuitement sur le site du Centre de Ressources Terre de Liens, dont la vocation est de “sensibiliser, documenter, inspirer et outiller toute personne souhaitant s’engager pour la préservation des terres agricoles et l’agroécologie”.</p><p>&nbsp;</p><p><strong>Des dossiers thématiques vous sont proposés en fonction de la nature de votre projet.</strong></p><p>&nbsp;</p><h2>Je souhaite transmettre mes terres ou ma ferme&nbsp;</h2><p>&nbsp;</p><p><strong>Consulter le dossier sur le </strong><a href="https://ressources.terredeliens.org/"><strong>Centre de Ressources</strong></a><strong> de Terre de Liens</strong> :</p><p>&nbsp;</p>', '2020-08-28 16:47:20', '2020-09-22 11:19:38', 0);
DELETE FROM `cms_pages` WHERE `id`=37;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (37, 'Confier mes terres', 'confier-mes-terres-partager-son-patrimoine-de-don', '“Partager son patrimoine… de don”', '<h2>Faire une donation ou un legs à Terre de Liens</h2><p>Partager son patrimoine, c’est faire acte de don. Par son aspect définitif, le don permet à Terre de Liens de sécuriser des terres de manière irréversible et d’assurer pleinement le maintien de leur vocation agricole sans limitation dans le temps. Les donations et legs constituent un appui financier sans égal dans la mesure où ils permettent de répondre à l’enjeu crucial poursuivi par Terre de Liens&nbsp;: faire sortir les terres du marché spéculatif sans possible retour en arrière, pour les traiter en biens communs dédiés à l’agriculture.</p><p>Pour autant, les donations possibles ne se limitent pas aux terres ou biens immobiliers en milieu rural&nbsp;: tous les types de patrimoines, matériels et immatériels, peuvent faire l’objet d’un don utile.</p><p>&nbsp;</p><p>&lt;iframe width="560" height="315" src="https://www.youtube.com/embed/Nkxi7iu0Lfw" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen&gt;&lt;/iframe&gt;</p><p>&nbsp;</p><p><strong>Pour aller plus loin, découvrez notre brochure :</strong></p><p>&nbsp;</p><p>&nbsp;</p>', '2020-08-28 16:47:20', '2020-09-23 11:44:40', 0);
DELETE FROM `cms_pages` WHERE `id`=38;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (38, 'Confier mes terres', 'confier-mes-terres-contenu-section-contactez-nous', 'Contenu section "Contactez-nous"', '<h2>Nous contacter au sujet des legs et donations</h2><p>Emmanuel Jaccaud, chargé de Patrimoine à Terre de Liens, est votre interlocuteur. Vous avez une question sur le don, le legs, la donation ou l’assurance vie, remplissez le formulaire ci-dessous, nous vous répondrons dans les meilleurs délais.</p>', '2020-08-28 16:47:20', '2020-09-23 11:45:18', 0);
DELETE FROM `cms_pages` WHERE `id`=39;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (39, 'Trouver une terre ou des financements', 'trouver-une-terre-ou-des-financements-texte-dintroduction-sous-le-titre-principal-et-vos-terres-vont-nourrir-denvergure', 'Contenu de la page "Trouver une terre ou des financements"', '<p>Pour vous aider, vous inspirer et vous outiller dans votre projet d’installation ou de transmission agricole, Terre de Liens et ses partenaires du réseau InPACT (Initiatives pour une Agriculture citoyenne et territoriale) ont édité un ensemble de guides méthodologiques et recueilli une diversité de projets réussis et inspirants d’installations et de transmissions.</p><p>L’ensemble de ces ressources vous sont mises à disposition gratuitement sur le site du <a href="https://ressources.terredeliens.org/">Centre de Ressources Terre de Liens</a>, dont la vocation est de “sensibiliser, documenter, inspirer et outiller toute personne souhaitant s’engager pour la préservation des terres agricoles et l’agroécologie”.</p><p>&nbsp;</p><p><strong>Des dossiers thématiques vous sont proposés en fonction de la nature de votre projet.</strong></p><h2>Je recherche des terres pour mon projet agricole&nbsp;</h2><p>&nbsp;</p><p><strong>Consulter le dossier sur le </strong><a href="https://ressources.terredeliens.org/"><strong>Centre de Ressources</strong></a><strong> de Terre de Liens :</strong></p>', '2020-08-28 16:47:20', '2020-09-22 14:38:53', 0);
DELETE FROM `cms_pages` WHERE `id`=42;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (42, 'M’installer comme paysan', 'minstaller-comme-paysan-texte-dintroduction-sous-le-titre-principal', 'Texte d’introduction sous le titre principal', '<h2>M\'installer paysan</h2><p>Pour vous aider, vous inspirer et vous outiller dans votre projet d’installation ou de transmission agricole, Terre de Liens et ses partenaires du réseau InPACT (Initiatives pour une Agriculture citoyenne et territoriale) ont édité un ensemble de guides méthodologiques et recueilli une diversité de projets réussis et inspirants d’installations et de transmissions.</p><p>&nbsp;</p><p>L’ensemble de ces ressources vous sont mises à disposition gratuitement sur le site du <a href="https://ressources.terredeliens.org/">Centre de Ressources Terre de Liens</a>, dont la vocation est de “sensibiliser, documenter, inspirer et outiller toute personne souhaitant s’engager pour la préservation des terres agricoles et l’agroécologie”.</p><p>&nbsp;</p><p><strong>Des dossiers thématiques vous sont proposés en fonction de la nature de votre projet.</strong></p>', '2020-08-28 16:47:20', '2020-09-22 12:51:39', 0);
DELETE FROM `cms_pages` WHERE `id`=43;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (43, 'M’installer comme paysan', 'minstaller-comme-paysan-votre-projet-dinstallations', '“Votre projet d’installations”', '<h2>Je souhaite m\'installer et devenir paysan-ne</h2><p>Ce dossier revient notamment sur les différentes étapes d’un projet d’installation, de l’idée à la concrétisation de votre projet. Il décline les possibilités de formation pour se confronter au métier de paysan-ne, notamment le test agricole, mais aussi les structures qui peuvent vous accompagner tout au long de votre projet d’installation. Après avoir balayé les principaux guides méthodologiques et pratiques à destination des néo-paysan-ne-s, vous trouverez également dans ce dossier des informations sur les étapes administratives obligatoires pour obtenir le statut d’agriculteur.&nbsp;</p>', '2020-08-28 16:47:20', '2020-09-22 12:50:14', 0);
