INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (53, 'Trouver un emploi', 'trouver-un-emploi-texte-dintroduction-sous-le-titre-principal-et-votre-plateforme-agricole', 'Texte d’introduction sous le titre principal et “Votre plateforme… agricole”', '<h2>Titre Section</h2><p>Facere non nulla placeat mollitia. Libero nobis ea labore eius mollitia quas. Veritatis quae quo et ex sed suscipit.\n\nMagnam molestiae repellat aut est nostrum autem. Rerum veniam eius aliquid exercitationem autem eum earum et. Quia ex perferendis nesciunt quae impedit officia non quod. Corrupti et iste unde.</p>', '2020-08-28 16:47:20', '2020-08-28 16:47:21', 0);
