INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (54, 'Trouver un emploi', 'trouver-un-emploi-texte-sous-le-bloc-dimages', 'Texte sous le bloc d’images', '<h2>Titre Section</h2><p>Qui aut non cumque aliquid. Labore at quod molestiae totam consequatur dignissimos accusantium. Repellendus commodi non iure nostrum.\n\nIn nihil quas sed est inventore sunt. Ut quasi laborum voluptatibus sunt minus. Illo qui sint deserunt illo non quia aut. Reiciendis assumenda voluptas facilis totam voluptate.</p>', '2020-08-28 16:47:20', '2020-08-28 16:47:21', 0);
DELETE FROM `cms_pages` WHERE `id`=55;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (55, 'Trouver un emploi', 'trouver-un-emploi-avez-vous-besoin-dun-conseil-demploi', '“Avez-vous besoin d’un conseil… d’emploi ?”', '<h2>Titre Section</h2><p>Corrupti ea veritatis quasi unde facere excepturi iure omnis. Consequatur officiis impedit labore fugit. Temporibus dolores laborum expedita dicta neque delectus doloribus. Laudantium quas sit magni consequatur.\n\nVoluptatem velit doloremque aut quia provident fuga. Nihil dolore omnis mollitia temporibus. Nesciunt delectus fugiat sapiente nam aperiam. Suscipit dolor veniam quibusdam alias in fugiat incidunt. Consequatur sunt aut cumque est illum distinctio eius exercitationem.</p>', '2020-08-28 16:47:20', '2020-08-28 16:47:21', 0);
DELETE FROM `cms_pages` WHERE `id`=56;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (56, 'Être accompagné', 'etre-accompagne-texte-dintroduction-sous-le-titre-principal', 'Texte d’introduction sous le titre principal', '<p>Terre de Liens peut vous accompagner sur <strong>le volet foncier</strong> de votre projet, que vous soyez :&nbsp;</p><ul><li><strong>en recherche de terres</strong> en vue d’une installation</li><li><strong>en recherche de financements</strong> pour des terres ou une ferme que vous avez identifié</li><li><strong>dans une démarche de transmission de votre ferme ou de votre bien agricole</strong>, en tant qu’agricultrice ou agriculteur bientôt à la retraite ou en tant que propriétaire privé</li></ul><p>Avant de nous contacter, nous vous invitons à consulter les pages <i>Je souhaite</i> et <i>Je suis</i> d’Objectif Terres : <strong>un recueil de guides et de ressources vous est proposé</strong> pour vous outiller dans votre recherche de terres ou dans votre projet de transmission.</p>', '2020-08-28 13:47:20', '2020-09-07 13:29:25', 0);
DELETE FROM `cms_pages` WHERE `id`=57;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (57, 'Mentions légales', 'mentions-legales-toutes-les-mentions-legales', 'Toutes les mentions légales', '<h4><strong>Informations générales sur l’éditeur du site</strong></h4><p>Le site public objectif-terres.org est édité par l’association Terre de Liens, association loi 1901, déclarée en sous-préfecture de Die</p><p>Siret&nbsp;: 480 509 645 00028 | APE&nbsp;: 9499Z<br>Directeur de publication&nbsp;: Michel Vampouille, président<br>Siège social&nbsp;: 1 rue Joseph Richard 26400 Crest</p><p>&nbsp;</p><h4><strong>Responsabilité quant au contenu</strong></h4><p>Terre de Liens s’efforce de vérifier et mettre à jour le contenu de son site. Pour autant, elle ne peut donner aucune garantie quant à l’ensemble des informations présentes sur le site, qu’elles soient fournies par ses soins, par ses partenaires ou par tout tiers, par l’envoi d’e-mails ou de toute autre forme de communication.</p><p>Compte tenu des caractéristiques du réseau Internet que sont la libre captation des informations diffusées et la difficulté, voire l’impossibilité, de contrôler l’utilisation qui pourrait en être faite par des tiers, Terre de Liens n’apporte aucune garantie quant à l’utilisation desdites informations.</p><p>Terre de Liens ne saurait en conséquence être tenue pour responsable du préjudice ou dommage pouvant résulter de l’utilisation des annonces et des informations présentes sur le site, ni d’erreurs ou omissions dans celles-ci.</p><p>Terre de Liens décline toute responsabilité en ce qui concerne les contenus des sites web édités par des tiers et accessibles depuis&nbsp;objectif-terres.org&nbsp;par des liens hypertextes.</p><p>&nbsp;</p><h4><strong>Protection des données personnelles</strong></h4><p><i>Collecte d’information</i></p><p>En créant un compte sur objectif-terres.org, en remplissant un formulaire de dépôt d\'annonce ou de demande d\'accompagnement ou un formulaire de contact, d’adhésion, de don, d’inscription à notre newsletter sur notre site&nbsp;objectif-terres.org, vous convenez et acceptez que Terre de Liens puisse recueillir, traiter, stocker et/ou utiliser les données personnelles soumises en conformité avec les règles exposées ci-après.</p><p>En nous donnant votre consentement, vous conservez également le droit de rectification, le droit à l’oubli et/ou le droit à la suppression de vos données personnelles.<br>Les informations que vous nous communiquez via ces formulaires font l’objet d’un traitement informatisé. Elles sont consultées par les salariés et bénévoles de l’association Terre de Liens en charge de suivre votre demande sur objectif-terres.org.</p><p>Les données personnelles que nous pouvons collecter&nbsp;:</p><ul><li>Vos informations de profil. Afin de vous identifier, nous pouvons vous demander de renseigner votre nom, prénom, civilité, votre adresse e-mail et postale, numéro de téléphone, votre sexe. Pour les personnes morales, la dénomination, forme juridique et contact des représentant légale et/ou du mandataire sociales.</li><li>Vos informations de transaction et de paiement. Lorsque vous effectuez un don, une adhésion ou une souscription, nous collectons certaines informations financières vous concernant notamment la date et l’heure du don, le montant du don et autres détails afférents à la transaction. En aucun cas, les informations liées à votre carte bancaire ne sont connues par Terre de Liens lorsque vous effectuez une transaction financière en ligne. Ces données confidentielles sont traitées automatiquement et uniquement via le programme de gestion sécurisée de paiement en ligne Ingenico et Paypal. Vous ne devez sous aucun prétexte communiquer les données de votre carte bancaire par un autre biais.</li></ul><p>Tous nos fichiers de données sont en conformité avec les recommandations de la CNIL et la législation française. Terre de Liens est en accord avec ces obligations au vue des deux déclarations CNIL n°&nbsp;1759395 et 1760726.<br>Aucune information personnelle n’est collectée à votre insu.&nbsp;<br>&nbsp;</p><p>Conformément à la loi Informatique et Libertés N°78-17 du 6 janvier 1978, en vous adressant à Terre de Liens, vous pouvez demander leur modification, leur rectification.</p><p>&nbsp;</p><h4><strong>Modifier ses abonnements et se désabonner</strong></h4><p>Nous utilisons l’adresse e-mail que vous fournissez pour vous envoyer nos newsletters. Si à n’importe quel moment vous souhaitez modifier vos abonnements à nos publications ou vous désinscrire et ne plus recevoir d’e-mails, des instructions de désabonnement détaillées sont incluses en bas de chaque e-mail. Vous pouvez également nous contacter à l’adresse objectif-terres@terredeliens.org&nbsp;</p><p>&nbsp;</p><h4><strong>Consentement</strong></h4><p>En utilisant notre site, vous consentez à notre politique de confidentialité.</p><p><i>Prestataires de services&nbsp;</i></p><p>Nous recourons à divers prestataires de service tiers afin de nous aider à fournir les services en lien avec Terre de Liens&nbsp;: Ces prestataires de service disposent d’un accès limité à vos informations dans le cadre de l’exécution de ces tâches pour notre compte, et ont une obligation contractuelle de les utiliser en conformité avec les termes de la présente politique de confidentialité.</p><p>IRAISER<br>Prestataire de gestion des dons en ligne. Lien vers leur&nbsp;<a href="https://www.iraiser.eu/fr/notre-engagement-securite/">politique de confidentialité.</a></p><p>MAILCHIMP<br>Prestataire de routage d’emailing. Lien vers leur&nbsp;<a href="https://mailchimp.com/legal/">politique de confidentialité.</a></p><p>SALESFORCE<br>Base de données et hébergeur. Lien vers leur&nbsp;<a href="https://www.salesforce.com/fr/company/privacy/">politique de confidentialité.</a></p><p>&nbsp;</p>', '2020-08-28 16:47:20', '2020-10-12 11:18:45', 0);
DELETE FROM `cms_pages` WHERE `id`=58;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (58, 'Aide et Ressources', 'aide-et-ressoures-responsable-territorial-text-dintroduction', 'Responsable Territorial-Text d\'introduction', '<p>Retrouvez ici toutes les ressources disponibles :</p><ul><li>autour de la modération des annonces : charte, ensemble des réponses types disponibles, etc.</li><li>autour des demandes d\'accompagnements</li><li>sur le site Objectif Terres : tutoriels d\'utilisation, conditions d\'utilisation, etc.</li></ul><p>&nbsp;</p><p>Cette section sera mise à jour progressivement. Pour faire remonter une ressource qui n\'apparaît pas ici : objectif-terres@terredeliens.org&nbsp;</p>', '2020-08-28 16:47:20', '2020-09-18 16:11:23', 0);
