INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (68, 'FAQ', 'faq', 'Contenu de la page FAQ', '<h2>Questions fréquentes</h2><h3>GÉRER MON COMPTE</h3><ul><li><strong>Pourquoi créer un compte sur Objectif Terres ?</strong></li></ul><p>La création d’un compte est gratuite. Elle vous permet :</p><p>- de déposer une annonce</p><p>- d’échanger directement avec un annonceur</p><p>- de solliciter un accompagnement auprès d’une association régionale Terre de Liens</p><p>- d’échanger directement avec les accompagnateurs de l’association régionale, si un accompagnement est effectivement enclenché&nbsp;</p><p>&nbsp;</p><ul><li><strong>Comment gérer mes informations personnelles ?&nbsp;</strong></li></ul><p>Une fois connecté, cliquer sur <i>Accéder à mon compte</i> en haut à droite puis sur <i>Mes informations</i>. Vous pouvez alors modifier vos informations personnelles et le fait de recevoir ou non des communications de Terre de Liens.&nbsp;</p><h3>TRANSPARENCE DU SERVICE</h3><ul><li><strong>Qui modère les annonces ?</strong></li></ul><p>Une trentaine de bénévoles et de salarié-es de Terre de Liens, réparti-es sur toute la France métropolitaine. Au regard de notre <a href="https://ressources.terredeliens.org/les-ressources/charte-de-terre-de-liens">charte</a> et des valeurs défendues par notre mouvement, chaque annonce est étudiée avec soin pour s’assurer qu’elle a bien sa place sur Objectif Terres.&nbsp;</p><p>&nbsp;</p><ul><li><strong>Qui répond aux demandes d’accompagnement ?</strong></li></ul><p>Une quarantaine de bénévoles et de salarié-es de Terre de Liens, formé-es à l’accompagnement réparti-es sur toute la France métropolitaine. Chaque association régionale a son fonctionnement propre sur l’organisation de l’accueil et de l’accompagnement des porteurs de projet et différentes modalités pourront vous être proposées : échanges de mails, point téléphonique, rendez-vous physique, réunion collective, etc.</p><p>&nbsp;</p><ul><li><strong>Que fait Terre de Liens de mes informations ?</strong></li></ul><p>Notre politique de confidentialité est disponible ici.</p><h3>DÉPOSER ET GÉRER DES ANNONCES</h3><ul><li><strong>Mon annonce ne rentre pas dans les catégories d’Objectif Terres, où puis-je déposer mon annonce ?</strong></li></ul><p><i>Votre annonce concerne un projet d’habitat collectif ou la recherche d’un lieu de vie :</i></p><p>&nbsp;→ Le magazine Passerelles éco propose un service d’annonces pour les écolieux de vie, les contacts ou échanges qui facilitent la recherche d’un lieu :&nbsp; <a href="https://www.passerelleco.info/article.php?id_article=256">https://www.passerelleco.info/article.php?id_article=256</a></p><p>&nbsp;→ Relie toits, site d’annonces et de partage pour les projets d’habitats participatifs : <a href="http://relie-toits.org/wakka.php?wiki=Habitatparticipatif">http://relie-toits.org/wakka.php?wiki=Habitatparticipatif</a></p><p>&nbsp;→ Le magazine l’Âge de faire : <a href="https://lagedefaire-lejournal.fr/petites-annonces/">https://lagedefaire-lejournal.fr/petites-annonces/</a></p><p>&nbsp;→ La coopérative Oasis, pour la création de nouveaux lieux de vie écologiques et solidaires : <a href="https://cooperative-oasis.org/">https://cooperative-oasis.org/</a></p><p>&nbsp;</p><p><i>Votre annonce concerne la vente et la recherche de matériel, de cheptel ou de fourrage :</i></p><p>&nbsp;→ Le site développé par la FNAB pour des échanges directs entre agriculteurs bio. Il concerne tous types d’annonces : fourrages, grains, services, matériel etc : <a href="https://www.agribiolien.fr/">https://www.agribiolien.fr/</a></p><p>&nbsp;→ La rubrique petites annonces du site de la Fédération des ADEAR : <a href="https://www.agriculturepaysanne.org/">https://www.agriculturepaysanne.org/</a></p><p>&nbsp;→ Les annonces de la Confédération paysanne à retrouver :</p><p>- sur leur site internet (<a href="https://www.confederationpaysanne.fr/petites_annonces.php">https://www.confederationpaysanne.fr/petites_annonces.php</a>)</p><p>- ou dans leur magazine Campagnes solidaires (<a href="https://www.confederationpaysanne.fr/campagnes_solidaires.php?dernier=1">https://www.confederationpaysanne.fr/campagnes_solidaires.php?dernier=1</a>)</p><p>&nbsp;</p><p><i>Votre annonce concerne l’accueil ou la recherche de volontariat sur une ferme :</i></p><p>&nbsp;→ Vivre et apprendre dans des fermes et jardin biologiques avec le wwoofing : <a href="https://wwoof.fr/">https://wwoof.fr/</a></p><p>&nbsp;→ Help Exchange (pas uniquement agricole) : <a href="https://www.helpx.net/hostlist.asp?host_state_id=67&amp;network=328">https://www.helpx.net/hostlist.asp?host_state_id=67&amp;network=328</a></p><p>→ Workaway : <a href="https://www.workaway.info/fr/hostlist/europe/fr">https://www.workaway.info/fr/hostlist/europe/fr</a></p><p>&nbsp;</p><p><i>Votre annonce concerne une recherche ou un partage de jardin :</i></p><p>→ <a href="https://www.plantezcheznous.com/">https://www.plantezcheznous.com/</a></p><p>→ <a href="http://www.pretersonjardin.com/">http://www.pretersonjardin.com/</a></p><p>→ <a href="https://www.jepartagemonjardin.fr/recherche-partage-jardin.php">https://www.jepartagemonjardin.fr/recherche-partage-jardin.php</a></p><p>&nbsp;</p><p><i>Votre annonce concerne un chantier participatif :</i></p><p>→ Dans les actualités de Terre de Liens, où des chantiers sont parfois organisé sur les fermes : <a href="https://terredeliens.org/-actualites-.html">https://terredeliens.org/-actualites-.html</a></p><p>→ Réseau de l’habitat écologique Twiza : <a href="https://fr.twiza.org/chantiers-participatifs/v2">https://fr.twiza.org/chantiers-participatifs/v2</a></p><p>&nbsp;</p><ul><li><strong>J’ai un projet collectif agricole : dans quelle catégorie déposer mon annonce ?</strong></li></ul><p><strong>→ Vous avez déjà un collectif constitué, et vous cherchez des terres pour vous installer</strong> : postez votre annonce dans la catégorie “Je cherche du foncier agricole” ; vous pourrez alors préciser s’il s’agit d’une installation individuelle, en couple ou en collectif</p><p>&nbsp;</p><p><strong>→Vous souhaitez rejoindre ou créer un collectif</strong> : postez votre annonce dans la catégorie “Je cherche une opportunité professionnelle” ; vous pourrez alors préciser que vous recherchez des associés ou des membres pour un collectif</p><p>&nbsp;</p><p><strong>→Vous souhaitez proposer à une personne de rejoindre votre collectif qui est déjà installé </strong>: postez votre annonce dans la catégorie “Je propose une opportunité professionnelle” ; vous pourrez alors préciser si vous recherchez un associé ou nouveau membre pour votre collectif&nbsp;</p><p>&nbsp;</p><ul><li><strong>Comment supprimer ou modifier mon annonce ?</strong></li></ul><p>Une fois connecté, cliquer sur <i>Accéder à mon compte </i>en haut à droite puis sur <i>Mes annonces</i>. Vous pouvez alors voir votre annonce et la supprimer ou la modifier.</p><p>&nbsp;</p><ul><li><strong>Une annonce ou la réponse à votre annonce vous semble frauduleuse, que faire ?</strong></li></ul><p>Nous vous invitons à faire preuve de vigilance : notre service d’annonces foncières est régulièrement la cible d’investisseurs ou autres sociétés prétendument spécialisées en prêts financiers, pour qui la plateforme est une opportunité de démarcher de nouveaux publics. Nous ne pouvons malheureusement pas filtrer l’ensemble des messages et des utilisateurs pour vous éviter ce type de pratiques frauduleuses.</p><p>Soyez donc particulièrement prudents dans la communication de vos informations personnelles. Pour faire remonter un problème de la sorte et éviter le désagrément à d’autres utilisateurs, merci de nous signaler l’annonce ou la réponse en question à travers <a href="https://portail-terredeliens.force.com/rhizome/s/signaler-un-abus">ce formulaire</a>.</p><p>&nbsp;</p><ul><li><strong>Qu\'est-ce qu\'une annonce "certifiée" ?</strong></li></ul><p>Il s\'agit d\'une annonce dont nous avons l\'habitude de travailler avec l\'annonceur en question : que ce soit une association régionale Terre de Liens, une structure qui accompagne les porteurs de projet comme une ADEAR ou un CIVAM, une collectivité locale dans le cadre d\'un appel à candidatures, etc. Ces annonces sont rédigées et/ou relues par des professionnels de l\'accompagnement et peuvent donc revêtir un intérêt particulier pour vos recherches de foncier et d\'opportunités professionnelles !</p><h3>SOLLICITER UN ACCOMPAGNEMENT</h3><ul><li><strong>Je n’ai pas eu de réponse à ma sollicitation, que faire ?</strong></li></ul><p>Les accompagnateurs et accompagnatrices de Terre de Liens rassemblent des salarié-es, qui sont souvent en déplacement sur le terrain, mais aussi des bénévoles, dont le temps et la disponibilité peuvent également être limités.&nbsp;Nous faisons notre possible pour répondre à vos demandes d’accompagnement. Patience !</p><p>&nbsp;</p><ul><li><strong>Je n’ai pas suffisamment d’informations pour compléter le formulaire</strong></li></ul><p>Les formulaires ont été pensés à la fois pour des candidats à l’installation en recherche opérationnelle de terres et pour des agriculteurs et propriétaires privés qui ont un bien agricole à disposition ou à transmettre. Vous êtes peut-être dans la situation où vous commencez à structurer votre projet agricole. Dans ce cas, Terre de Liens n’est pas l’interlocuteur le plus indiqué. Un ensemble de contacts et de ressources vous sont présentés sur le Centre de Ressources de Terre de Liens :</p><p><a href="https://ressources.terredeliens.org/les-ressources/je-souhaite-devenir-paysan">&nbsp;-que vous ayez le souhait de devenir paysan-ne</a></p><p><a href="https://ressources.terredeliens.org/les-ressources/en-cours-je-recherche-des-terres-pour-mon-projet-agricole">&nbsp;-que vous commenciez à recherche du foncier</a></p><p><a href="https://ressources.terredeliens.org/les-ressources/je-transmets-mes-terres-ou-ma-ferme">&nbsp;-ou que vous commenciez à réfléchir à un projet de transmission</a></p>', '2020-09-22 10:21:20', '2020-10-12 12:28:43', 0);
DELETE FROM `cms_pages` WHERE `id`=69;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (69, 'Propriétaire de foncier', 'proprietaire-de-foncier', 'Contenu page "Propriétaire de foncier"', '<p>Pour vous aider, vous inspirer et vous outiller dans votre projet d’installation ou de transmission agricole, Terre de Liens et ses partenaires du réseau InPACT (Initiatives pour une Agriculture citoyenne et territoriale) ont édité un ensemble de guides méthodologiques et recueilli une diversité de projets réussis et inspirants d’installations et de transmissions.</p><p>L’ensemble de ces ressources vous sont mises à disposition gratuitement sur le site du <a href="https://ressources.terredeliens.org/">Centre de Ressources Terre de Liens</a>, dont la vocation est de “sensibiliser, documenter, inspirer et outiller toute personne souhaitant s’engager pour la préservation des terres agricoles et l’agroécologie”.</p><p>&nbsp;</p><p><strong>Un dossier thématique à destination des propriétaires privés qui se posent la question du devenir agricole de leur bien ou qui souhaitent en orienter l\'usage, par exemple vers des pratiques agricoles plus respectueuses de l\'environnement sera bientôt disponible. Terre de Liens éditera d\'ici 2021 un guide de la propriété foncière agricole pour vous outiller en ce sens. N\'hésitez pas à revenir ultérieurement sur cette page !</strong></p><p>&nbsp;</p><p>En attendant, vous pouvez consulter ci-dessous le guide foncier pour proprié\'terre, qui apporte des éclairages techniques, méthodologiques et juridiques à destination des propriétaires de foncier :</p>', '2020-09-23 11:27:00', '2020-09-23 13:51:24', 0);
DELETE FROM `cms_pages` WHERE `id`=71;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (71, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-1', 'Text du territoire Alsace', '<p>&nbsp;Les terres agricoles sont rares et chères en Alsace, la pression est telle que peu d’opportunités sont relayées sur les plateformes d’annonces. L’association <a href="https://terredeliens.org/auvergne.html">Terre</a> de Liens Alsace vous accueille et vous oriente que vous soyez porteur de projet à l’installation, à la transmission ou propriétaire privé pour vous rendre le plus autonome possible dans la recherche de terres ou de repreneurs. Nous vous invitons dans un premier temps à vous inscrire à une de nos soirées d’information collectives qui a lieu environ tous les 2 mois puis au sein d’ateliers thématiques collectifs, les inscriptions, c’est par ici : <a href="https://forms.gle/4FKR8ZGEfZE68Lfy7">https://forms.gle/4FKR8ZGEfZE68Lfy7</a></p><p>Au plaisir de vous rencontrer !</p>', '2020-09-23 13:00:04', '2020-09-23 15:50:27', 0);
DELETE FROM `cms_pages` WHERE `id`=72;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (72, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-2', 'Text du territoire Aquitaine', '<p><i>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour 2021 !</i></p><p>&nbsp;</p><p>En attendant, vous pouvez nous contacter en utilisant l’un des formulaires suivants : <a href="https://terredeliens.org/aquitaine.html">https://terredeliens.org/aquitaine.html</a></p><p>&nbsp;</p>', '2020-09-23 13:03:04', '2020-09-23 17:06:44', 0);
DELETE FROM `cms_pages` WHERE `id`=73;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (73, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-3', 'Text du territoire Auvergne', '<p>L’association Terre de Liens Auvergne fonctionne grâce à la mobilisation de citoyennes et citoyens bénévoles organisé·e·s en groupes locaux. Chaque groupe s\'organise de façon autonome pour mener ses actions sur son territoire, notamment l’accueil, l’orientation et l’accompagnement des candidates et candidats à l\'installation et à la transmission. En Auvergne, il y a un groupe local par département : Allier, Cantal, Haute-Loire et Puy-de-Dôme.</p><p>Nous vous mettrons en relation avec le groupe local de votre territoire de prédilection.</p>', '2020-09-23 13:03:04', '2020-09-23 15:48:36', 0);
DELETE FROM `cms_pages` WHERE `id`=74;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (74, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-4', 'Text du territoire Bourgogne / Franche-Comté', '<p>Vous désirez être accompagnés pour votre projet d’installation, de transmission ou pour toutes questions relatives au foncier agricole : l’association Terre de Liens Bourgogne Franche-Comté vous accueille et vous accompagne par l\'intermédiaire d’une quinzaine de référent.e.s installation-transmission, réparti.es sur l’ensemble du territoire régional.</p><p>Vous serez recontacté au plus vite par la personne référente de votre territoire afin de mieux cerner votre projet.&nbsp;</p><p>A bientôt !</p>', '2020-09-23 12:03:04', '2020-09-23 15:52:38', 0);
DELETE FROM `cms_pages` WHERE `id`=75;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (75, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-5', 'Text du territoire Bretagne', '<p><i>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt !</i></p><p>&nbsp;</p><p>L’association <a href="https://terredeliens.org/bretagne.html">Terre de Liens Bretagne Liamm an Douar</a> fonctionne grâce à la mobilisation de ses adhérents et de ses bénévoles engagés, pour la préservation du foncier agricole en Bretagne. Elle est aujourd’hui représentée par 12 bénévoles administrateurs répartis sur toute la Bretagne, et est appuyée par 3 salarié.e.s qui travaillent notamment à l’accompagnement des porteurs de projet à l’installation agricole.&nbsp;</p><p>Pour entrer en contact avec nous dans le cadre de votre projet, n’hésitez pas à contacter Damien, animateur à Terre de Liens Bretagne, au 06 68 22 07 16 ou à l’adresse : <a href="mailto:bretagne@terredeliens.org">bretagne@terredeliens.org</a></p><p>Pour soutenir notre association et son action en Bretagne, vous pouvez adhérer ! Bulletin d’adhésion disponible <a href="https://cloud.inpact35.org/terredeliens/s/JyYiJCcJerLRMgJ#pdfviewer">&gt;&gt;&gt;ici&lt;&lt;&lt;</a></p>', '2020-09-23 13:03:04', '2020-09-23 16:49:26', 0);
DELETE FROM `cms_pages` WHERE `id`=76;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (76, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-6', 'Text du territoire Centre', '<p>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt.</p><p>&nbsp;</p><p>En attendant, vous pouvez nous contacter en utilisant l’un des formulaires suivants :</p><p><a href="https://terredeliens.org/centre.html">https://terredeliens.org/centre.html</a></p>', '2020-09-23 12:03:04', '2020-09-23 15:55:21', 0);
DELETE FROM `cms_pages` WHERE `id`=77;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (77, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-7', 'Text du territoire Champagne-Ardenne', '<p><i>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt.</i></p><p>Terre de Liens Champagne-Ardenne vous accueille et vous oriente que vous soyez porteur de projet à l’installation, cédant à la recherche d’un repreneur ou propriétaire privé.</p><p>Pour nous contacter, écrivez-nous à l’adresse suivante : <a href="mailto:champagne-ardenne@terredeliens.org">champagne-ardenne@terredeliens.org</a> en précisant les contours de votre projet et en laissant vos coordonnées téléphoniques. Le salarié ou un bénévole de l’association vous recontactera rapidement.</p><p>Pour soutenir notre association et son action en Champagne-Ardenne, vous pouvez également adhérer <a href="https://soutenir.terredeliens.org/adhesion/~mon-don">&nbsp;en cliquant ici</a> !</p>', '2020-09-23 13:03:04', '2020-09-23 15:52:06', 0);
DELETE FROM `cms_pages` WHERE `id`=78;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (78, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-8', 'Text du territoire Corsica', '<p>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt.</p><p>&nbsp;</p><p>En attendant, vous pouvez nous contacter en utilisant l’un des formulaires suivants :</p><p><a href="https://terredeliens.org/corsica.html">https://terredeliens.org/corsica.html</a></p><p>&nbsp;</p>', '2020-09-23 13:03:04', '2020-09-23 15:55:41', 0);
DELETE FROM `cms_pages` WHERE `id`=79;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (79, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-9', 'Text du territoire Hauts-de-France', '<p><i>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour 2021 !</i></p><p>Vous désirez être accompagné·es pour votre projet d\'installation ou pour toutes questions relatives au foncier agricole ? L\'association Terre de Liens Hauts-de-France et ses bénévoles vous accueillent. Vous pouvez nous contacter ici :</p><p><a href="https://terredeliens.org/hauts-de-france.html">https://terredeliens.org/hauts-de-france.html</a></p><p>Nous vous invitons dès à présent à être le plus précis possible dans votre demande, afin de nous permettre de mieux vous guider.</p><p>&nbsp;</p><p>A très bientôt !</p>', '2020-09-23 13:03:04', '2020-09-23 17:05:57', 0);
DELETE FROM `cms_pages` WHERE `id`=80;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (80, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-10', 'Text du territoire Ile-de-France', '<p><i>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt. En attendant, vous pouvez utiliser le formulaire de contact classique suivant :</i></p><p><a href="https://terredeliens.org/ile-de-france-76-76.html"><i>https://terredeliens.org/ile-de-france-76-76.html</i></a></p><p>&nbsp;</p><p>Les terres agricoles sont rares et chères en Ile-de-France, la pression est telle que peu d’opportunités sont relayées sur les plateformes d’annonces. L’association Terre de Liens Ile-de-France vous accueille et vous oriente :&nbsp;</p><p>&gt; Si vous êtes porteur.euse de projet à l’installation, Terre de Liens IdF et ses partenaires du <a href="http://devenirpaysan-idf.org/">Pôle Abioso</a>l vous accompagnent dans votre projet, de l’idée à la concrétisation de l’installation. Pour participer à une réunion d’information, contactez Jemma (<a href="mailto:jemma@abiosol.org">jemma@abiosol.org</a>)&nbsp;</p><p>&gt; Si vous êtes propriétaire privé ou agriculteur cédant en recherche de preneurs de terres, un membre de l’association reprendra contact avec vous pour vous accompagner dans votre projet.</p>', '2020-09-23 13:03:04', '2020-09-23 15:51:34', 0);
DELETE FROM `cms_pages` WHERE `id`=81;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (81, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-11', 'Text du territoire Languedoc-Roussillon', '<p>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt.</p><p>&nbsp;</p><p>En attendant, vous pouvez nous contacter en utilisant l’un des formulaires suivants :</p><p><a href="https://terredeliens.org/languedoc-roussillon-77.html">https://terredeliens.org/languedoc-roussillon-77.html </a>ou &nbsp;<a href="https://www.terredelienslr.fr/contact/">https://www.terredelienslr.fr/contact/</a></p><p>&nbsp;</p>', '2020-09-23 13:03:04', '2020-09-23 15:54:22', 0);
DELETE FROM `cms_pages` WHERE `id`=82;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (82, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-12', 'Text du territoire Limousin', '<p>Vous désirez être accompagné.e pour votre projet d’installation ou de transmission en agriculture nourricière, paysanne et biologique, bravo. L’association Terre de Liens Limousin vous accueille et vous accompagne par l\'intermédiaire d’une dizaine de citoyen.nes mobilisé.es et réparti.es sur les trois départements.&nbsp;</p><p>Vous serez recontacté.e au plus vite par un bénévole du département de votre choix. Afin de préparer au mieux votre accompagnement, nous vous invitons dès à présent à être le plus précis possible dans votre demande.</p><p>A bientôt !</p>', '2020-09-23 12:03:04', '2020-09-23 16:58:45', 0);
DELETE FROM `cms_pages` WHERE `id`=83;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (83, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-13', 'Text du territoire Lorraine', '<p>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt.</p><p>&nbsp;</p><p>En attendant, vous pouvez utiliser le formulaire de contact classique suivant :</p><p><a href="https://terredeliens.org/lorraine.html">https://terredeliens.org/lorraine.html</a></p><p>&nbsp;</p>', '2020-09-23 13:03:04', '2020-09-23 15:53:11', 0);
DELETE FROM `cms_pages` WHERE `id`=84;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (84, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-15', 'Text du territoire Midi-Pyrénées', '<p>Vous désirez être accompagnés pour votre projet d’installation, de transmission ou pour toutes questions relatives au foncier agricole : l’association Terre de Liens Midi-Pyrénées vous accueille et vous accompagne par l\'intermédiaire d’une quinzaine de citoyen.nes mobilisé.es et réparti.es sur l’ensemble du territoire régional.</p><p>&nbsp;</p><p>Vous serez recontacté au plus vite par ces bénévoles. Afin de préparer au mieux votre accompagnement, nous vous invitons dès à présent à être le plus précis possible dans votre demande qui leur sera transmise.</p><p>&nbsp;</p><p>A bientôt !</p>', '2020-09-23 13:03:04', '2020-10-04 17:44:36', 0);
DELETE FROM `cms_pages` WHERE `id`=85;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (85, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-16', 'Text du territoire Normandie', '<p>Vous désirez être accompagnés pour votre projet d’installation, de transmission ou pour toutes questions relatives au foncier agricole : l’association Terre de Liens Normandie vous accueille et vous accompagne par l\'intermédiaire d’une dizaine de bénévoles et 4 animateurs salariés répartis sur l’ensemble du territoire régional.</p><p>Vous serez recontacté au plus vite par ces bénévoles ou salariés. Afin de préparer au mieux votre accompagnement, nous vous invitons dès à présent à être le plus précis possible dans votre demande qui leur sera transmise.</p><p>A bientôt !</p>', '2020-09-23 13:03:04', '2020-09-23 15:55:04', 0);
DELETE FROM `cms_pages` WHERE `id`=86;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (86, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-17', 'Text du territoire Pays de la Loire', '<p>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt.</p><p>&nbsp;</p><p>L\'association Terre de Liens Pays de la Loire fonctionne grâce à la mobilisation de ses adhérents et de ses bénévoles engagés, pour la préservation du foncier agricole en Pays de la Loire. Elle est représentée par des bénévoles répartis sur l\'ensemble de la région et appuyés par deux salarié.e.s, qui travaillent notamment à l\'accompagnement des porteurs de projet à l\'installation agricole.</p><p>Pour entrer en contact avec nous dans le cadre de votre projet, n\'hésitez pas nous écrire sur <a href="http://pdl@terredeliens.org/">pdl@terredeliens.org</a>, en précisant les contours de votre projet.</p><p>Pour soutenir notre association et son action en Pays de la Loire, vous pouvez adhérer ! Le bulletin d\'adhésion est téléchargeable <a href="http://passeursdeterres.org/wp-content/uploads/2020/03/Bulletin-dadh%C3%A9sion-TDL-PDL-2020.pdf">&gt;&gt;&gt; ici &lt;&lt;&lt;</a>.</p>', '2020-09-23 13:03:04', '2020-09-23 15:51:05', 0);
DELETE FROM `cms_pages` WHERE `id`=87;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (87, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-19', 'Text du territoire Poitou-Charentes', '<p><i>Objectif Terres est un service en cours de déploiement. Le territoire que vous avez sélectionné ne fait pas encore parti des Associations Régionales Terre de Liens utilisant cet outil. Patience, c’est pour bientôt.</i></p><p>&nbsp;</p><p>Pour contacter l''association <a target="_blank" href="https://terredeliens.org/poitou-charentes">Terre de Liens Poitou Charentes</a>, vous pouvez utiliser le formulaire suivant :</p><p><a target="_blank" href="https://terredeliens.org/spip.php?page=contact&amp;contact=84 ">https://terredeliens.org/spip.php?page=contact&amp;contact=84&nbsp;</a></p>', '2020-09-23 13:03:04', '2020-10-04 17:38:30', 0);
DELETE FROM `cms_pages` WHERE `id`=88;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (88, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-20', 'Text du territoire PACA', '<p>Vous désirez être accompagnés pour votre projet d’installation, de transmission ou pour toutes questions relatives au foncier agricole : l’association Terre de Liens PACA vous accueille grâce à la mobilisation de ses adhérents et de ses bénévoles engagés, réparti.es sur l’ensemble du territoire régional pour vous rendre le plus autonome possible dans la recherche de terres ou de repreneurs.</p><p>Nous vous invitons dès à présent à être le plus précis possible dans votre demande, afin de nous permettre de mieux vous guider.</p><p>Vous serez recontacté au plus vite par une personne référente de votre territoire de prédilection afin de mieux cerner votre projet.&nbsp;</p>', '2020-09-23 13:03:04', '2020-09-23 15:52:52', 0);
DELETE FROM `cms_pages` WHERE `id`=89;
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (89, 'Être accompagné', 'etre-accompagne-text-du-territoire-numero-21', 'Text du territoire Rhône-Alpes', '<p>L’association Terre de Liens Rhône-Alpes fonctionne grâce à la mobilisation de citoyennes et citoyens bénévoles organisé·e·s en groupes locaux. Chaque groupe s\'organise de façon autonome pour mener ses actions sur son territoire, notamment l’accueil, l’orientation et l’accompagnement des candidates et candidats à l\'installation et à la transmission.</p><p>Vous pouvez découvrir la carte des groupes locaux de la région <a target="_blank" href="https://ba41891a-a-62cb3a1a-s-sites.googlegroups.com/site/terredeliensraportailintranet/home/les-groupes-locaux/191231_carte_fermes_GL_TdLRA.png?attachauth=ANoY7crUD1OLetcDaLyOKyBBu78V3cum0aNh-YvFC69a6Dwf8UgP4E7ZowFCQwkduKhGkOFZKd0N-Ns10ogT2cxJAI1wzUHycArGXad1RMf_CQ-efsP1yFM3L3pUn2BUvlK3RBheEGMPr2XEsFZ6KU1na6bH6dbbO8trJr4ycOye7K2Cqcwk42K6UOUD-gKIHxmI7RMoHxwUPQ64XQVlTPzQ8d9xpMCF5qWACyc0GxJIIVjhflNnLsFOGym8ODuHvH2fmXnh7pNuw0rQCfydhzgOk1Vc786btirMmN5pATKpMCQ41lMSTLM%3D&amp;attredirects=1">en suivant ce lien</a>.&nbsp;</p><p>Nous vous mettrons en relation avec le groupe local de votre territoire.</p>', '2020-09-23 13:03:04', '2020-09-25 14:29:29', 0);
INSERT INTO `cms_pages` (`id`, `page_name`, `slug`, `description`, `content`, `created_at`, `updated_at`, `has_documents`) VALUES (90, 'Conditions utilisation', 'conditions-utilisation-toutes-les-conditions-dutilisation-du-site-dobjectif-terres', 'Toutes les conditions d''utilisation du site d''Objectif Terres', '', '2020-10-26 15:44:49', '2020-10-26 15:44:49', 0);



